<?php foreach(['hora_inicio'=>'Hora inicial','hora_fin'=>'Hora final'] as $field=>$label): ?><div class="col-md-6"><label for="<?= $field ?>" class="form-label"><?= $label ?> *</label><input type="text" inputmode="decimal" pattern="([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9](\.[0-9]{1,6})?)?|24:00(:00(\.0{1,6})?)?" placeholder="HH:MM" class="form-control" id="<?= $field ?>" name="<?= $field ?>" required value="<?= $escape($values[$field]) ?>" aria-describedby="time-help"></div><?php endforeach; ?>
